spawn-at-startup "/nix/store/HASH-niri-spawn-wrapper" "/nix/store/HASH-firefox-145.0.1/bin/firefox"
spawn-at-startup "/nix/store/HASH-niri-spawn-wrapper" "/nix/store/HASH-kitty-0.44.0/bin/kitty"
spawn-at-startup "/nix/store/HASH-niri-spawn-wrapper" "/nix/store/HASH-ddcutil-2.2.3/bin/ddcutil" "--model=XWU-CBA" "setvcp" "0x60" "0x0f"
spawn-at-startup "/nix/store/HASH-niri-spawn-wrapper" "/nix/store/HASH-kitty-0.44.0/bin/kitten" "desktop-ui" "run-server"
window-rule {
    geometry-corner-radius 10.000000 10.000000 10.000000 10.000000
    clip-to-geometry true
}
layer-rule {
    match namespace="^wallpaper$"
    place-within-backdrop true
}
